using System;
using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "FallenStarOmenData", menuName = "Data/Battle/Omens System/Omen Data/Event/FallenStarOmenData")]
public class FallenStarOmenData : OmenData
{
	[Header("CodexOfBurdensOmenData Omen")]
	[SerializeField]
	private PlayerCurrentRunes playerCurrentRunes;

	[SerializeField]
	private OmenData risingStarOmenData;

	[SerializeField]
	private PlayerCurrentOmens playerCurrentOmens;

	[SerializeField]
	private OmensListsList omensListsList;

	private Action startBattleOmenAction;

	private Action endOfBattleOmenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		startBattleOmenAction = delegate
		{
			omenInstance.EnqueueOmenFeedbackAndPlay();
			playerCurrentRunes.SetPlayerHaveFallenStar(value: true);
			playerCurrentRunes.DisableAllRunes();
		};
		endOfBattleOmenAction = delegate
		{
			bool flag = false;
			if (EnableOmenCounter)
			{
				counter++;
				omenInstance.UpdateOmenCounter();
				if (counter == TriggerAmount)
				{
					flag = true;
				}
			}
			else
			{
				flag = true;
			}
			if (flag)
			{
				OmenRemoved();
				RuntimeOmenData item = new RuntimeOmenData(risingStarOmenData, 0);
				int runtimeOmenIndex = playerCurrentOmens.GetRuntimeOmenIndex(this);
				playerCurrentOmens.RuntimeOmens.RemoveAt(runtimeOmenIndex);
				playerCurrentOmens.RuntimeOmens.Insert(runtimeOmenIndex, item);
				omenInstance.Initialize(risingStarOmenData);
				risingStarOmenData.Initialize(omenInstance);
				omenInstance.EnqueueOmenFeedbackAndPlay();
				omensListsList.BlessingDiscovered(risingStarOmenData);
			}
		};
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.StartOfBattleOmenActions.Add(startBattleOmenAction);
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.EndOfBattleOmenActions.Add(endOfBattleOmenAction);
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.StartOfBattleOmenActions.Remove(startBattleOmenAction);
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.EndOfBattleOmenActions.Remove(endOfBattleOmenAction);
		playerCurrentRunes.SetPlayerHaveFallenStar(value: false);
	}

	public override string OmenConvertedDescription()
	{
		return Smart.Format(GetOmenRawLocalizedDescription(), TriggerAmount, ActionValue);
	}
}
